INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3301, 'Leviticus 23:26', 'Leviticus', 23, 26, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3302, 'Leviticus 23:27', 'Leviticus', 23, 27, '&nbsp;”د دې اوومې مياشتې لسمه ورځ د کفارې ده، دا به ستاسو دپاره يوه مقدسه اجتماع وى. تاسو به روژه نيسئ او مالِک خُدائ ته په اور تيارېدونکې نذرانه پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3303, 'Leviticus 23:28', 'Leviticus', 23, 28, '&nbsp;په هغه ورځ هيڅ کار مۀ کوئ، ځکه چې هغه د کفارې ورځ ده او د مالِک خُدائ ستاسو خُدائ پاک وړاندې ستاسو کفاره ادا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3304, 'Leviticus 23:29', 'Leviticus', 23, 29, '&nbsp;هر څوک چې هم په هغه ورځ څۀ وخورى نو هغه به نور د خُدائ پاک د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3305, 'Leviticus 23:30', 'Leviticus', 23, 30, '&nbsp;او کۀ هر چا هم په هغه ورځ څۀ کار وکړو، نو زۀ به په خپله هغه تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3306, 'Leviticus 23:31', 'Leviticus', 23, 31, '&nbsp;ستاسو اولاد چې چرته هم اوسيږى دا اصُول د هغوئ دپاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3307, 'Leviticus 23:32', 'Leviticus', 23, 32, '&nbsp;د هغې مياشتې د نهمې ورځې د نمرپرېواتو نه د لسمې ورځې د نمرپرېواتو پورې دا خاص ورځ مانځئ، په دې دوران کښې تاسو روژه نيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3308, 'Leviticus 23:35', 'Leviticus', 23, 35, '&nbsp;د دې ورځو په وړومبۍ ورځ د عبادت دپاره راغونډ شئ او هغه يو کار هم مۀ کوئ چې تاسو يې هره ورځ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3309, 'Leviticus 23:36', 'Leviticus', 23, 36, '&nbsp;اووۀ ورځې تاسو هره ورځ يوه په اور تيارېدونکې نذرانه پېش کوئ. په اتمه ورځ بيا د عبادت دپاره راغونډ شئ او په اور تيارېدونکې نذرانه پېش کړئ. دا د عبادت ورځ ده او چې هيڅ کار په کښې ونۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3310, 'Leviticus 23:37', 'Leviticus', 23, 37, '&nbsp;دا مذهبى اخترونه دى چې تاسو يې د مالِک خُدائ په درناوى کښې کوئ چې د عبادت دپاره په يو ځائ راغونډېږئ او په اور تيارېدونکې نذرانې، سوزېدونکې نذرانې، د غلې نذرانې، قربانۍ او د ميو نذرانې په کښې پېش کوئ، چې په خپله خپله ورځ پېش کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3311, 'Leviticus 23:38', 'Leviticus', 23, 38, '&nbsp;دا اخترونه د عامو سبت د ورځو نه علاوه دى او دا نذرانې ستاسو د عامو تُحفو نه علاوه دى، ستاسو د منښتې پوره کېدلو نذرانو او ستاسو د هغه رضاکارانه نذرانو نه چې تاسو يې مالِک خُدائ له ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3312, 'Leviticus 23:39', 'Leviticus', 23, 39, '&nbsp;کله چې تاسو د خپلو پټو نه فصل ورېبئ، نو اووۀ ورځې دا اختر کوئ، چې د اوومې مياشتې په پينځلسمه ورځ باندې شروع کيږى. اوله ورځ او اتمه ورځ به د آرام کولو خاص ورځې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3313, 'Leviticus 23:40', 'Leviticus', 23, 40, '&nbsp;په هغه ورځ د خپلو ونو نه ډېره ښۀ مېوه وشوکوئ، د کجورو څانګې او د پاڼو والا د ونو څانګې او د سيند د غاړې نه د خاروَلو ونې واخلئ او د مالِک خُدائ ستاسو خُدائ پاک په درناوى کښې اختر وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3314, 'Leviticus 23:41', 'Leviticus', 23, 41, '&nbsp;دا اووۀ ورځې کوئ. ستاسو اولاد به دا اصُول په راتلونکى ټولو وختونو کښې منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3315, 'Leviticus 23:42', 'Leviticus', 23, 42, '&nbsp;ټول اِسرائيل به اووۀ ورځې په جونګړو کښې اوسيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3316, 'Leviticus 23:43', 'Leviticus', 23, 43, '&nbsp;چې ستاسو اولاد ته دا پته ولګى چې مالِک خُدائ اِسرائيليان دې ته جوړ کړل چې په جونګړو کښې اوسيږى چې کله يې هغوئ د مِصر مُلک نه راوويستل. هغه مالِک خُدائ ستاسو خُدائ پاک دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3317, 'Leviticus 23:44', 'Leviticus', 23, 44, '&nbsp;نو داسې موسىٰ بنى اِسرائيلو ته دا اصُول وښودل چې د مالِک خُدائ په درناوى کښې مذهبى اخترونه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3318, 'Leviticus 24:1', 'Leviticus', 24, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3319, 'Leviticus 24:2', 'Leviticus', 24, 2, '&nbsp;”بنى اِسرائيلو له حُکم ورکړه چې د ډيوو دپاره ډېر ښۀ سوچه د زيتُونو تېل راوړى کومې چې په مقدسه خېمه کښې دى، نو چې هر وخت رڼا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3320, 'Leviticus 24:3', 'Leviticus', 24, 3, '&nbsp;هارون به هر ماښام دا ډيوې بلوى او تر سحره پورې به يې بلې ساتى، چې د مالِک خُدائ په حضور کښې د پړدې نه بهر د لوظ صندوق ته مخامخ دى، دا ډيوټ په زيات مقدس ځائ کښې دے. دا اصُول دې په راتلونکى ټولو وختونو کښې منلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3321, 'Leviticus 24:4', 'Leviticus', 24, 4, '&nbsp;هارون به د هغه ډيوو خيال ساتى کومې چې د سوچه سرو زرو په ډيوټ باندې دى او دې ته به پام کوى چې دا د مالِک خُدائ په حضور کښې هر وخت بليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3322, 'Leviticus 24:5', 'Leviticus', 24, 5, '&nbsp;دولس کلو ښۀ اوړۀ واخله او دولس روټۍ ترې نه پخې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3323, 'Leviticus 24:6', 'Leviticus', 24, 6, '&nbsp;په دوه ډېرو کښې يې په هغه مېز باندې کېږده چې د سوچه سرو زرو پترى ورباندې خېژولے شوے دے، کوم چې د مالِک خُدائ په حضور کښې دے او چې په هر ډيرى کښې شپږ شپږ روټۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3324, 'Leviticus 24:7', 'Leviticus', 24, 7, '&nbsp;په هر ډيرى باندې څۀ سوچه لوبان واچوه، دا به مالِک خُدائ ته په اور تيارېدونکې نذرانې د يوې نښې په شان وى چې د روټۍ په ځائ پېش کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3325, 'Leviticus 24:8', 'Leviticus', 24, 8, '&nbsp;د هر سبت په ورځ په راتلونکو ټولو وختونو کښې، روټۍ دې خامخا د مالِک خُدائ په حضور کښې کېښودلے شى. د بنى اِسرائيلو همېشه دپاره دا لوظ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3326, 'Leviticus 24:9', 'Leviticus', 24, 9, '&nbsp;دا روټۍ د هارون او د هغۀ د اولاد ده او هغوئ به دا په يو مقدس ځائ کښې خورى، ځکه چې دا د اِمامانو دپاره مالِک خُدائ ته په اور تيارېدونکې نذرانې يوه ډېره مقدسه برخه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3327, 'Leviticus 24:12', 'Leviticus', 24, 12, '&nbsp;هغه يې قېد کړو او مالِک خُدائ ته يې اِنتظار کولو چې هغوئ ته وښائى چې د هغۀ سره څۀ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3328, 'Leviticus 24:13', 'Leviticus', 24, 13, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3329, 'Leviticus 24:14', 'Leviticus', 24, 14, '&nbsp;”دا سړے د خېمو نه بهر بوځئ. هر چا چې د هغۀ کنځل اورېدلى وى نو هغه به خپل لاس د هغه سړى په سر د ګواهۍ ورکولو دپاره کېږدى او بيا به ټول قوم هغه سنګسار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3330, 'Leviticus 24:15', 'Leviticus', 24, 15, '&nbsp;بيا اِسرائيلو ته ووايه چې هر څوک هم خُدائ پاک ته کنځل وکړى نو هغۀ ته به خامخا د خپلو بدو سزا مِلاو شى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3331, 'Leviticus 24:16', 'Leviticus', 24, 16, '&nbsp;او وبه وژلے شى. هر يو اِسرائيلے يا د پردى مُلک کس چې ستاسو سره اوسيږى چې هغه مالِک خُدائ ته کنځل وکړى نو ټول قوم دې هغه ووژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3332, 'Leviticus 24:17', 'Leviticus', 24, 17, '&nbsp;هر څوک چې قتل وکړى نو هغه به وژلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3333, 'Leviticus 24:18', 'Leviticus', 24, 18, '&nbsp;او هر څوک چې د بل چا يو ځناور ووژنى نو تاوان به يې خامخا ورکوى. دا اصُول د ژوند په بدل کښې د ژوند والا دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3334, 'Leviticus 24:19', 'Leviticus', 24, 19, '&nbsp;کۀ څوک يو بل کس زخمى کړى، هغۀ چې څۀ هم کړى وى نو هم هغه شان عمل به ورسره کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3335, 'Leviticus 24:20', 'Leviticus', 24, 20, '&nbsp;کۀ هغه يو هډوکے مات کړى، نو د هغۀ يو هډوکے به ماتولے شى، کۀ هغه يوه سترګه وباسى نو د هغۀ يوه سترګه به ويستلے شى، کۀ هغه يو غاښ مات کړى، نو د هغۀ يو غاښ به ماتولے شى. هغه چې څنګه هم بل کس زخمى کړى نو په بدل کښې به د هغۀ سره هم هغه عمل کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3336, 'Leviticus 24:21', 'Leviticus', 24, 21, '&nbsp;هر څوک چې يو ځناور ووژنى نو تاوان به يې ورکوى، خو هر څوک چې يو انسان ووژنى نو هغه به ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3337, 'Leviticus 24:22', 'Leviticus', 24, 22, '&nbsp;دا قانون ستاسو د ټولو دپاره دے، کۀ هغه اِسرائيلے وى يا د پردى مُلک کس چې ستاسو سره اوسيږى، ځکه چې زۀ مالِک خُدائ ستاسو خُدائ پاک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3338, 'Leviticus 24:23', 'Leviticus', 24, 23, '&nbsp;کله چې موسىٰ بنى اِسرائيلو ته دا وفرمائيل، نو هغوئ هغه سړے د خېمو نه بهر بوتلو چا چې کنځل کړى وُو او سنګسار يې کړو. نو بنى اِسرائيلو هم هغه شان وکړل چې څنګه مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3339, 'Leviticus 25:1', 'Leviticus', 25, 1, '&nbsp;بيا مالِک خُدائ د سينا په غرۀ باندې موسىٰ ته وفرمائيل او حُکم يې ورکړو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3340, 'Leviticus 25:2', 'Leviticus', 25, 2, '&nbsp;”بنى اِسرائيلو ته دا اصُول وښايه. کله چې تاسو هغه مُلک ته ورننوځئ چې مالِک خُدائ يې تاسو له درکوى، د مالِک خُدائ د درناوى دپاره په هر اوؤم کال تاسو هغه زمکه مۀ کَرئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3341, 'Leviticus 25:3', 'Leviticus', 25, 3, '&nbsp;شپږ کاله به تاسو خپل پټى وکَرئ، په باغونو کښې به د انګورو څانګې قينچى کړئ او فصلونه به راغونډ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3342, 'Leviticus 25:4', 'Leviticus', 25, 4, '&nbsp;خو په اوؤم کال دې زمکه شاړه پاتې شى. دا به مالِک خُدائ ته وقف شوے کال وى. خپل پټى مۀ کَرئ او په خپلو باغونو کښې د انګورو څانګې مۀ قينچى کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3343, 'Leviticus 25:5', 'Leviticus', 25, 5, '&nbsp;هغه فصل مۀ رېبئ چې د کَرلو نه بغېر په خپله راشين کيږى او د خپلو باغونو نه هغه انګور مۀ راټولوئ چې څانګې يې قينچى شوى نۀ وى، دا هغه کال دے چې زمکه به په کښې پوره آرام کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3344, 'Leviticus 25:6', 'Leviticus', 25, 6, '&nbsp;کۀ په هغه کال کښې زمکه کَرلے شوې هم نۀ وى، خو د هغې نه به ستاسو دپاره، ستاسو نوکرانو، مزدورانو او د مسافرو دپاره چې ستاسو سره اوسيږى، خوراک مِلاو شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3345, 'Leviticus 25:7', 'Leviticus', 25, 7, '&nbsp;داسې ستاسو څاروو دپاره او ستاسو په پټو کښې د ځنګلى ځناورو دپاره هم. زمکه چې هر څۀ راشنۀ کړى نو هغه خوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3346, 'Leviticus 25:8', 'Leviticus', 25, 8, '&nbsp;اووۀ ځلې اووۀ کالونه وشمېرئ چې يو کم پنځوس کاله جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3347, 'Leviticus 25:9', 'Leviticus', 25, 9, '&nbsp;نو د اوومې مياشتې په لسمه ورځ يعنې د کفارې په ورځ به په ټول مُلک کښې بيګل وغږولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3348, 'Leviticus 25:10', 'Leviticus', 25, 10, '&nbsp;نو تاسو پنځوسم کال خاص وګڼئ او د مُلک ټولو خلقو ته د آزادۍ اِعلان وکړئ. په دې کال هغه هر څۀ هم چې خرڅ شوى وى نو هغه به اصلى مالِک يا د هغۀ اولاد ته واپس ملاويږى او هر څوک چې د غلام په توګه خرڅ شوے وى نو هغه به خپل خاندان ته واپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3349, 'Leviticus 25:11', 'Leviticus', 25, 11, '&nbsp;تاسو به خپل پټى نۀ کَرئ نۀ به هغه فصل رېبئ چې په خپله راشين شوے وى او نۀ به په باغونو کښې هغه انګور راټولوئ چې څانګې يې پرې کړے شوې نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3350, 'Leviticus 25:12', 'Leviticus', 25, 12, '&nbsp;هغه ټول کال به ستاسو دپاره مقدس وى، تاسو به صِرف هغه څۀ خورئ چې پټو په خپله راشنۀ کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3351, 'Leviticus 25:13', 'Leviticus', 25, 13, '&nbsp;په دې کال هغه هر څۀ چې خرڅ شوى وى نو هغه به واپس خپل اصلى مالِک ته مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3352, 'Leviticus 25:14', 'Leviticus', 25, 14, '&nbsp;کله چې تاسو په خپل وطندار ورور باندې زمکه خرڅوئ يا يې ترې نه اخلئ، نو يو بل له دوکه مۀ ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3353, 'Leviticus 25:15', 'Leviticus', 25, 15, '&nbsp;قيمت به يې د کالونو د شمېر په مطابق مقررولے شى چې په هغه زمکه کښې د واپس ورکولو کال نه مخکښې څومره فصل کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3354, 'Leviticus 25:16', 'Leviticus', 25, 16, '&nbsp;کۀ چرې پاتې شوى کالونه ډېر وى، نو قيمت به يې اوچت وى، خو کۀ صِرف يو څو کالونه پاتې وى، نو قيمت به يې کم وى، ځکه چې څۀ هم خرڅيږى نو هغه د فصلونو د هغه شمېر په مطابق به وى چې په هغه زمکه کښې پېدا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
