(3356, 'Leviticus 25:18', 'Leviticus', 25, 18, '&nbsp;د مالِک خُدائ ټول قانون او حُکمونه منئ، نو تاسو به هغه مُلک کښې په امن سره اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3357, 'Leviticus 25:19', 'Leviticus', 25, 19, '&nbsp;هغه زمکه به فصلونه پېدا کوى او د خوراک هغه هر څۀ به درته ملاويږى چې تاسو يې غواړئ او په امن کښې به ژوند تېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3358, 'Leviticus 25:20', 'Leviticus', 25, 20, '&nbsp;خو کېدے شى چې ستاسو نه يو کس تپوس وکړى چې پټى ونۀ کَرلے شى او فصلونه راغونډ نۀ شى نو په اوؤم کال به څۀ خورو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3359, 'Leviticus 25:21', 'Leviticus', 25, 21, '&nbsp;مالِک خُدائ به په شپږم کال هغه زمکې له برکت ورکړى نو هغه زمکه به د دوه کالونو دپاره ښۀ ډېر خوراک پېدا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3360, 'Leviticus 25:22', 'Leviticus', 25, 22, '&nbsp;کله چې تاسو په اتم کال خپل پټى کَرئ، نو چې په شپږم کال تاسو څۀ رېبلى وى هغه به تر اوسه پورې خورئ او په نهم کال به هم تاسو هغه څۀ خورئ کوم چې تاسو په اتم کال کَرئ او رېبئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3361, 'Leviticus 25:23', 'Leviticus', 25, 23, '&nbsp;تاسو خپله زمکه د همېشه دپاره مۀ خرڅوئ، ځکه چې زمکه ستاسو نۀ ده، د خُدائ پاک ده او تاسو د مسافرو په شان يئ چا ته چې دا اجازت وى چې صِرف ګټه ترې نه واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3362, 'Leviticus 25:24', 'Leviticus', 25, 24, '&nbsp;کله چې زمکه خرڅيږى، نو د دې د اصلى مالِک د واپس اخستلو حق به خامخا منلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3363, 'Leviticus 25:25', 'Leviticus', 25, 25, '&nbsp;کۀ يو اِسرائيلے غريب شى او زمکې خرڅولو ته مجبور شى، نو د هغۀ د ټولو نه نزدې خپلوان به زمکه واپس اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3364, 'Leviticus 25:26', 'Leviticus', 25, 26, '&nbsp;کۀ د چا خپلوان نۀ وى چې دا واپس واخلى نو کېدے شى وروستو مالدار شى او ډېرې پېسې ولرى چې دا واپس واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3365, 'Leviticus 25:27', 'Leviticus', 25, 27, '&nbsp;نو په داسې حال کښې به خامخا هغه سړى له قيمت ورکوى چا چې اخستې وى، دا قيمت به د واپس ورکولو کال پورې د پاتې کالونو دپاره وى، تر هغې پورې چې هغۀ ته خپله زمکه واپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3366, 'Leviticus 25:28', 'Leviticus', 25, 28, '&nbsp;خو کۀ د هغۀ سره ډېرې پېسې نۀ وى چې زمکه واپس واخلى نو دا به د واپس اخستلو نه وروستو کال پورې د هغه سړى په قبضه کښې وى. په هغه کال دې دا خپل اصلى مالِک ته واپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3367, 'Leviticus 25:29', 'Leviticus', 25, 29, '&nbsp;کۀ څوک په يو دېوال لرونکى ښار کښې کور خرڅ کړى، نو هغه د دې د خرڅېدو د تاريخ نه واخله په هغه وړومبى ټول کال د واپس اخستلو حق لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3368, 'Leviticus 25:30', 'Leviticus', 25, 30, '&nbsp;خو کۀ هغه يې په يو کال کښې واپس وانۀ خلى نو د واپس اخستلو حق د هغۀ د لاس نه لاړ شى او هغه کور به د اخستونکى او د هغۀ د اولاد د همېشه دپاره وى، دا به د واپس اخستلو په کال نۀ واپس کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3369, 'Leviticus 25:31', 'Leviticus', 25, 31, '&nbsp;خو چې کوم کورونه په بې‌دېواله کلو کښې دى نو په هغوئ به د پټو په شان کار کيږى، د دې اصلى مالِک دا حق لرى چې دا واپس واخلى او دا به د واپس اخستلو په کال کښې واپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3370, 'Leviticus 25:32', 'Leviticus', 25, 32, '&nbsp;خو، ليويان هر وخت دا حق لرى چې په ښارونو کښې خپل هغه جائيداد واپس واخلى چې هغوئ ته حواله شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3371, 'Leviticus 25:33', 'Leviticus', 25, 33, '&nbsp;کۀ چرې يو ليوے په ښارونو کښې يو کور خرڅ کړى او واپس وانۀ خستلے شى، نو د واپس کولو په کال کښې به دا خامخا واپس شى، ځکه چې د ليويانو په خپلو ښارونو کښې چې کوم کورونه دى دا د اِسرائيلو په مينځ کښې د هغوئ ذاتى جائيداد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3372, 'Leviticus 25:34', 'Leviticus', 25, 34, '&nbsp;خو د ليويانو د ښارونو نه ګېرچاپېره مېدان به هيڅکله نۀ خرڅيږى، دا د همېشه دپاره د هغوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3373, 'Leviticus 25:35', 'Leviticus', 25, 35, '&nbsp;کۀ ستاسو سره يو نزدې اوسېدونکے بنى اِسرائيلے دومره غريب شى چې خپل ځان نۀ شى ساتلے، نو تاسو خامخا د هغۀ مدد کوئ لکه څنګه چې تاسو د پردى مُلک کس سره مدد کوئ، نو چې هغه ستاسو سره نزدې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
