(3375, 'Leviticus 25:37', 'Leviticus', 25, 37, '&nbsp;تاسو چې کومې پېسې هغوئ له قرض ورکړئ نو د هغې سود ترې نه مۀ اخلئ او چې کوم خوراک ورباندې خرڅ کړئ د هغې ګټه ترې نه مۀ اخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
