(3386, 'Leviticus 25:48', 'Leviticus', 25, 48, '&nbsp;د هغۀ د خرڅېدو نه پس، هغه بيا هم دا حق لرى چې واپس واخستلے شى. د هغۀ يو ورور', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3387, 'Leviticus 25:49', 'Leviticus', 25, 49, '&nbsp;يا د هغۀ ترۀ، د ترۀ زوئ يا د هغۀ بل يو نزدې خپلوان هغه واپس اخستلے شى. يا کۀ هغه په خپله مالداره شى، نو هغه خپله آزادى په خپله اخستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3388, 'Leviticus 25:50', 'Leviticus', 25, 50, '&nbsp;چا چې هغه اخستے وى د هغۀ سره به خامخا مشوره کوى او هغوئ به د خرڅېدو د وخت نه واخله د واپس اخستلو نه وروستو کال پورې کالونه وشمېرى او چې کومې پېسې يو مزدور ته ورکولے کيږى د هغې په بنياد به د هغۀ د خلاصېدو قيمت مقرر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3389, 'Leviticus 25:53', 'Leviticus', 25, 53, '&nbsp;لکه چې هغه د کال په بنياد باندې مزدور کړے شوے وو. د هغۀ مالِک به د هغۀ سره ظلم نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3390, 'Leviticus 25:54', 'Leviticus', 25, 54, '&nbsp;کۀ هغه په داسې څۀ طريقه آزاد نۀ کړے شى، نو هغه او د هغۀ بچى به د واپس ورکولو د کال نه پس په بل کال خامخا آزاد کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3391, 'Leviticus 25:55', 'Leviticus', 25, 55, '&nbsp;يو اِسرائيلے به همېشه دپاره غلام نۀ وى، ځکه اِسرائيليان د مالِک خُدائ غلامان دى. هغۀ هغوئ د مِصر مُلک نه راوويستل، هغه مالِک خُدائ د هغوئ خُدائ پاک دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3392, 'Leviticus 26:1', 'Leviticus', 26, 1, '&nbsp;مالِک خُدائ وفرمائيل، ”بُتان، مجسمې، د کاڼو ستنې، يا داسې کاڼى مۀ جوړَوئ چې تاسو ورته سجده وکړئ. زۀ مالِک خُدائ ستاسو خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3393, 'Leviticus 26:2', 'Leviticus', 26, 2, '&nbsp;زما د سبت ورځ منئ او د هغه ځائ درناوے کوئ چرته چې زما عبادت کيږى. زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3394, 'Leviticus 26:3', 'Leviticus', 26, 3, '&nbsp;کۀ تاسو زما د قانون په مطابق ژوند تېروئ او زما حُکمونو ته غاړه کېږدئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3395, 'Leviticus 26:4', 'Leviticus', 26, 4, '&nbsp;نو زۀ به په صحيح وخت باران وروم، هغه زمکه به فصلونه پېدا کړى او ونې به مېوې ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3396, 'Leviticus 26:5', 'Leviticus', 26, 5, '&nbsp;ستاسو فصلونه به دومره ډېر وى چې د انګورو د راټولولو وخت پورې به تاسو غوبل کوئ او تر هغه پورې به انګور راټولوئ چې د غلې کَرلو وخت راورسيږى. د خوراک دپاره تاسو ته به هغه هر څۀ ملاويږى چې تاسو يې غواړئ او په خپل مُلک کښې به تاسو په امن ژوند کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3397, 'Leviticus 26:6', 'Leviticus', 26, 6, '&nbsp;زۀ به تاسو له ستاسو په مُلک کښې آرام درکړم او تاسو به بغېر د يرې نه خوب کوئ. زۀ به د هغه مُلک خطرناک ځناور لرې کړم او هلته به نور جنګ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3398, 'Leviticus 26:7', 'Leviticus', 26, 7, '&nbsp;تاسو به په خپلو دشمنانو بريالى شئ او تاسو به هغوئ په جنګ کښې ووژنئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3399, 'Leviticus 26:8', 'Leviticus', 26, 8, '&nbsp;ستاسو پينځۀ کسان به سلو له شکست ورکړى او سل کسان به لسو زرو له شکست ورکړى. ستاسو دشمنان به په جګړه کښې شکست وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3400, 'Leviticus 26:9', 'Leviticus', 26, 9, '&nbsp;زۀ به په تاسو نظر وکړم او ډېر اولاد به درکړم، زۀ به هغه لوظ پوره کړم چې ما ستاسو سره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');